function withoutPrivate(value){if(Array.isArray(value))return value.map(withoutPrivate);if(!isObject(value))return value;return Object.fromEntries(Object.entries(value).filter(([key])=>!['privateNotes','private_notes','battleRecords'].includes(key)).map(([key,item])=>[key,withoutPrivate(item)]));}
