 const campaign=await db.prepare('SELECT * FROM shared_campaigns WHERE id=?').bind(campaignId).first(),deleted=await db.prepare('SELECT owner_id FROM campaign_deletions WHERE campaign_id=?').bind(campaignId).first(),state=JSON.parse(doc.state);
