 requireValue(campaign?campaign.owner_id===userId:deleted?deleted.owner_id===userId:!!local,'캠페인 소유자만 삭제할 수 있습니다.',403);
 requireValue(!campaign||body.revision===campaign.revision,'캠페인이 변경되었습니다. 새로고침 후 다시 삭제하세요.',409);
 const serialized=validateState(removeCampaignState(state,campaignId)),token=uid(),at=stamp();
